import { marked } from "marked";
import { parse } from "yaml";

export type BookMeta = {
  slug: string;
  title: string;
  author: string;
  year: number;
  rating: number;
  tags: string[];
};
export type Book = BookMeta & { html: string };

const files = import.meta.glob("/content/books/*.md", {
  query: "?raw",
  import: "default",
  eager: true,
}) as Record<string, string>;

function parseBook(path: string, raw: string): Book {
  const slug = path.slice(path.lastIndexOf("/") + 1).replace(/\.md$/, "");
  const match = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/.exec(raw);
  const data = match ? parse(match[1]) : {};
  return {
    slug,
    title: String(data.title),
    author: String(data.author),
    year: Number(data.year),
    rating: Number(data.rating),
    tags: (data.tags ?? []).map(String),
    html: marked.parse(match ? match[2] : raw, { async: false }),
  };
}

const books: Book[] = Object.entries(files)
  .map(([path, raw]) => parseBook(path, raw))
  .sort((a, b) => (a.title < b.title ? -1 : a.title > b.title ? 1 : 0));

export function allBooks(): BookMeta[] {
  return books.map(({ html: _html, ...meta }) => meta);
}

export function findBook(slug: string): Book | null {
  return books.find(b => b.slug === slug) ?? null;
}
