import { MetaProvider } from "@solidjs/meta";
import { A, Router, useLocation } from "@solidjs/router";
import { FileRoutes } from "@solidjs/start/router";
import { Suspense } from "solid-js";
import "./app.css";

function Layout(props: { children?: any }) {
  const location = useLocation();
  const current = (section: string) => {
    const path = location.pathname.replace(/\/+$/, "") || "/";
    return path === section || path.startsWith(section + "/")
      ? ("page" as const)
      : undefined;
  };
  return (
    <>
      <header>
        <A href="/" end>Bookshelf</A>
        <nav aria-label="Main">
          <A href="/books" aria-current={current("/books")}>Books</A>
          <A href="/about" aria-current={current("/about")}>About</A>
          <A href="/contact" aria-current={current("/contact")}>Contact</A>
        </nav>
      </header>
      <main>
        <Suspense>{props.children}</Suspense>
      </main>
      <footer>© Bookshelf</footer>
    </>
  );
}

export default function App() {
  return (
    <MetaProvider>
      <Router root={Layout}>
        <FileRoutes />
      </Router>
    </MetaProvider>
  );
}
