import { Title } from "@solidjs/meta";
import { action, useSubmission } from "@solidjs/router";
import { createSignal, Show } from "solid-js";
import { validateContact, type ContactErrors } from "~/lib/validate";

type Result = {
  ok: boolean;
  values: { name: string; email: string; message: string };
  errors: ContactErrors;
};

const sendContact = action(async (formData: FormData): Promise<Result> => {
  "use server";
  const { validateContact } = await import("~/lib/validate");
  const field = (k: string) => formData.get(k)?.toString() ?? "";
  const { values, errors } = validateContact({
    name: field("name"),
    email: field("email"),
    message: field("message"),
  });
  return { ok: Object.keys(errors).length === 0, values, errors };
}, "contact");

export default function Contact() {
  const submission = useSubmission(sendContact);
  const [clientErrors, setClientErrors] = createSignal<ContactErrors | undefined>();

  const result = () => submission.result as Result | undefined;
  const errors = (): ContactErrors => clientErrors() ?? result()?.errors ?? {};
  const values = () => result()?.values;
  const success = () => {
    const r = result();
    return r && r.ok && !clientErrors() ? r : undefined;
  };

  const onSubmit = (e: SubmitEvent) => {
    const form = e.currentTarget as HTMLFormElement;
    const data = new FormData(form);
    const field = (k: string) => data.get(k)?.toString() ?? "";
    const { errors } = validateContact({
      name: field("name"),
      email: field("email"),
      message: field("message"),
    });
    if (Object.keys(errors).length) {
      e.preventDefault();
      setClientErrors(errors);
    } else {
      setClientErrors(undefined);
    }
  };

  return (
    <>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={success()}>
        {r => <p>Thanks, {r().values.name}! Your message has been sent.</p>}
      </Show>
      <form action={sendContact} method="post" novalidate onSubmit={onSubmit}>
        <div>
          <label for="name">Name</label>
          <input id="name" name="name" type="text" value={values()?.name ?? ""} />
          <Show when={errors().name}>{m => <p class="error">{m()}</p>}</Show>
        </div>
        <div>
          <label for="email">Email</label>
          <input id="email" name="email" type="email" value={values()?.email ?? ""} />
          <Show when={errors().email}>{m => <p class="error">{m()}</p>}</Show>
        </div>
        <div>
          <label for="message">Message</label>
          <textarea id="message" name="message" value={values()?.message ?? ""} />
          <Show when={errors().message}>{m => <p class="error">{m()}</p>}</Show>
        </div>
        <button type="submit">Send</button>
      </form>
    </>
  );
}
EOF
